#!/usr/bin/env python3
"""Append newly discovered Friend-Message utterances to episode files on main.

Usage: append_missing.py <native-repo> <main-worktree>
Prints a report; makes no commits.
"""
import json
import os
import re
import subprocess
import sys

NATIVE = sys.argv[1] if len(sys.argv) > 1 else "/tmp/shurik-workspace-uZzuCq"
MAIN = sys.argv[2] if len(sys.argv) > 2 else "/tmp/ross-main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
SEP = "\x1f"
REC = "\x1e"


def git(*args):
    return subprocess.run(
        ["git", "-C", NATIVE, *args], capture_output=True, text=True, check=True
    ).stdout


def parse_utterance(msg):
    lines = msg.split("\n")
    if "Friend-Message: 1" not in msg:
        return None
    speaker = episode = reply_to = None
    body_start = None
    for i, line in enumerate(lines):
        s = line.strip()
        if s.startswith("Speaker:"):
            speaker = s[len("Speaker:"):].strip()
        elif s.startswith("Episode:"):
            episode = s[len("Episode:"):].strip()
        elif s.startswith("Reply-To:"):
            reply_to = s[len("Reply-To:"):].strip()
            # utterance begins after the next blank line
            j = i + 1
            while j < len(lines) and lines[j].strip() == "":
                j += 1
            body_start = j
            break
    if not (speaker and episode and body_start is not None):
        return None
    body = "\n".join(lines[body_start:]).rstrip("\n")
    if not body.startswith(speaker + ":"):
        return None
    return {
        "speaker": speaker,
        "episode": episode,
        "reply_to": reply_to,
        "text": body,
    }


# collect utterances from all six branches (full history)
utterances = []
for b in BRANCHES:
    raw = git("log", f"--format={SEP.join(['%H', '%cI', '%B'])}{REC}", f"origin/friend/{b}")
    for chunk in raw.split(REC):
        chunk = chunk.strip("\n")
        if not chunk or "Friend-Message: 1" not in chunk:
            continue
        parts = chunk.split(SEP, 2)
        if len(parts) < 3:
            continue
        sha, ts, msg = parts
        parsed = parse_utterance(msg)
        if parsed:
            parsed.update(sha=sha, ts=ts, branch=f"friend/{b}")
            utterances.append(parsed)

# find published source SHAs in the main worktree
published = {}
ep_files = []
for root, _dirs, names in os.walk(MAIN):
    if os.path.basename(root) in (".git", "node_modules", "site"):
        continue
    for n in names:
        if re.match(r"^E\d\d\.md$", n) and os.path.basename(root).startswith("S"):
            path = os.path.join(root, n)
            ep_files.append(path)
            txt = open(path, encoding="utf-8").read()
            for sha in re.findall(r"Source: friend/\w+ @ ([0-9a-f]{40})", txt):
                published.setdefault(sha, path)

missing = [u for u in utterances if u["sha"] not in published]
by_ep = {}
for u in missing:
    by_ep.setdefault(u["episode"], []).append(u)

report = []
for ep, items in sorted(by_ep.items()):
    items.sort(key=lambda u: (u["ts"], u["sha"]))
    m = re.match(r"^(S\d\d)/(E\d\d)$", ep)
    if not m:
        report.append(f"SKIP invalid episode label: {ep}")
        continue
    path = os.path.join(MAIN, m.group(1), m.group(2) + ".md")
    if not os.path.exists(path):
        report.append(f"SKIP missing file for declared episode: {path}")
        continue
    existing = open(path, encoding="utf-8").read()
    # keep published order: append each new entry at the end
    add = []
    for u in items:
        add.append(
            f"**{u['speaker']}** ({u['ts']})\n\n"
            f"Source: {u['branch']} @ {u['sha']}\n\n"
            f"{u['text']}\n"
        )
    with open(path, "a", encoding="utf-8") as fh:
        if not existing.endswith("\n"):
            fh.write("\n")
        fh.write("\n" + "\n".join(add))
    report.append(f"appended {len(items)} to {path}")

print("\n".join(report) if report else "nothing missing")
print(f"total utterances={len(utterances)} published={len(published)} missing={len(missing)}")

