    if not (20<=w<=35): bad.append((p,meta.get('status'),w,'LEN'))
    if body!=s: bad.append((p,meta.get('status'),w,'PARA-MISMATCH'))
    if meta.get('status') not in ('ongoing','complete'): bad.append((p,meta.get('status'),w,'STATUS'))
print("issues:",len(bad))
