for p in sorted(glob.glob('S*/E*.md')):
    t=open(p,encoding='utf-8').read()
    body=t.split('---',2)[2]
    blocks=re.split(r'\n(?=\*\*)',body)
    seen=set()
    prev_ts=None
    for b in blocks:
        m=re.match(r'\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/(\w+) @ ([0-9a-f]{40})\n\n(.+?)\s*$',b,re.S)
        if not m:
            if b.strip():
                issues.append((p,'UNPARSED BLOCK',b[:80]))
            continue
        sp,ts,br,sha,text=m.groups()
        if sha in seen: issues.append((p,'DUP SHA',sha[:8]))
        seen.add(sha)
        if not text.startswith(sp+':'): issues.append((p,'SPEAKER MISMATCH',sha[:8],text[:50]))
        if prev_ts and ts<prev_ts: issues.append((p,'OUT OF ORDER',prev_ts,ts,sha[:8]))
